    // Encoder-decoder
    archHeading: 'Architekturvarianten',
    archIntro: 'Der ursprüngliche Transformer hatte einen Encoder und einen Decoder. Die meisten späteren Modelle behalten nur einen der beiden Stapel. Schalte zwischen den drei Varianten um, um zu sehen, welche Komponenten jede nutzt.',
