    arch_encoder_decoder_desc: 'Das ursprüngliche Design. Der Encoder liest die gesamte Eingabe bidirektional; der Decoder erzeugt die Ausgabe Token für Token und liest die Repräsentationen des Encoders per Cross-Attention. Typisch für Übersetzung und andere Sequence-to-Sequence-Aufgaben.',
    arch_encoder_only_desc: 'Nur der Encoder-Stapel mit bidirektionaler Attention – jedes Token sieht jedes andere. Stark bei Verständnisaufgaben wie Klassifikation, Named-Entity-Erkennung und Embeddings; nicht für freie Textgenerierung gebaut.',
    arch_decoder_only_desc: 'Nur der Decoder-Stapel mit kausaler Maske – jedes Token sieht nur sich selbst und frühere Tokens. Training auf Next-Token-Prediction und Textgenerierung nutzen dieselbe Rechnung; deshalb ist das heute das Standarddesign von LLMs.',
