    // Dataflow
    dataflowHeading: 'Token-Datenfluss in einem modernen Decoder',
    dataflowIntro: 'Verfolge einen Prompt aus 6 Tokens durch einen Pre-Norm-Decoder mit RoPE und Grouped-Query Attention – mit den echten Dimensionen von Llama 3 8B. Achte darauf, wie sich die Tensorform ändert und wo der Residual Stream aktualisiert wird.',
    dataflowTitle: 'Datenfluss Schritt für Schritt',
