    dataflowSymbolic: 'Symbolisch',
    dataflowConcrete: 'Llama 3 8B',
    flow_tokenize: 'Tokenisieren',
    flow_tokenize_desc: 'Ein BPE-Tokenizer zerlegt den Text in 6 Tokens und ordnet jedem eine ganzzahlige ID zu.',
    flow_embed: 'Einbetten',
    flow_embed_desc: 'Jede ID wählt eine Zeile der Embedding-Matrix. Diese Vektoren sind der Startwert des Residual Streams x – ein Positionsvektor wird nicht addiert.',
    flow_qkv: 'RMSNorm → Q, K, V',
    flow_qkv_desc: 'Eine normalisierte Kopie von x wird auf 32 Query-Heads, aber nur 8 Key/Value-Heads projiziert (Grouped-Query Attention): Je 4 Query-Heads teilen sich einen K/V-Head, das verkleinert den KV-Cache um den Faktor 4.',
    flow_rope: 'RoPE anwenden',
    flow_rope_desc: 'Paare von Dimensionen in Q und K werden um einen Winkel gedreht, der proportional zur Tokenposition ist. V bleibt ungedreht. Die Formen ändern sich nicht.',
    flow_scores: 'Attention-Scores',
    flow_scores_desc: 'softmax(QKᵀ / √128) pro Head mit kausaler Maske: Zeile t hat nur Gewichte für Positionen ≤ t. Diese T × T-Matrix ist der Grund, warum Standard-Attention quadratisch mit der Kontextlänge wächst.',
    flow_attn_out: 'Attention-Ausgabe + Residual',
