    blindNo: 'Nein',
    blindNewExample: 'Neues Beispiel',
    blindCorrect: 'Richtig. Die Geometrie ergibt: {answer}.',
    blindWrong: 'Nicht ganz. Die Geometrie ergibt: {answer}.',
    blindPublished: 'Veröffentlichte Genauigkeit bei dieser Aufgabe (BlindTest, 2024)',
    blindStimulusAlt: 'Erzeugtes geometrisches Testbild',

    // Fehlerbilder
    modesTitle: 'Fünf Fehlerbilder und ihre Mechanismen',
    modeMechanism: 'Mechanismus',
    modeHelps: 'Was hilft',
    modeCountingTitle: 'Zählen',
    modeCountingMechanism: 'Zum Zählen müssen einzelne Exemplare getrennt werden. Kontrastiv auf Bildunterschriften trainierte Encoder brauchten selten exakte Anzahlen, und überlappende oder benachbarte Objekte verschmelzen über Patch-Grenzen hinweg.',
    modeCountingHelps: 'Lass das Modell jedes Exemplar mit Punkt oder Box markieren und die Markierungen zählen, oder nutze einen spezialisierten Detektor.',
    modeSpatialTitle: 'Geometrie und räumliche Beziehungen',
    modeSpatialMechanism: 'Dünne Linien, Berührungspunkte und Links-rechts-Beziehungen stecken in wenigen Pixeln. Skalierung und Patches verwischen genau diese Stellen, und BlindTest zeigt, dass die Antworten deutlich besser werden, wenn Formen weit auseinanderliegen.',
    modeSpatialHelps: 'Bezugssystem ausdrücklich nennen, den kritischen Bereich zuschneiden oder Geometrie mit Code berechnen statt schätzen.',
    modeTextTitle: 'Kleine Schrift und feine Details',
    modeTextMechanism: 'Ist ein Buchstabe nach dem Skalieren kleiner als ein Patch (siehe Demo oben), vermischen sich seine Striche mit dem Hintergrund, bevor das Modell sie sieht. Nichts weiter hinten in der Pipeline kann sie wiederherstellen.',
    modeTextHelps: 'Höhere Auflösung senden, Textbereiche zuschneiden oder für kritische Zeichenfolgen echte OCR einsetzen.',
    modeHallucinationTitle: 'Visuelle Halluzination',
    modeHallucinationMechanism: 'Bei schwacher Bildevidenz setzt sich das Sprachvorwissen durch. POPE zeigte, dass Modelle besonders oft Objekte „sehen“, die häufig zusammen mit dem tatsächlich Abgebildeten vorkommen, etwa eine Tastatur neben einem Monitor.',
    modeHallucinationHelps: 'Ja/Nein-Fragen zu konkreten Objekten stellen, „nicht sichtbar“ als Antwort erlauben und kritische Details prüfen.',
    modeMultiTitle: 'Mehrere Bilder vergleichen',
    modeMultiMechanism: 'Vergleiche brauchen Korrespondenzen: Welche Region in Bild A gehört zu welcher in Bild B? Bei Projektor-Modellen sind beide Bilder nur getrennte Token-Blöcke. Einen expliziten Abgleichschritt gibt es nicht, das Modell muss die Zuordnung aus Daten lernen.',
    modeMultiHelps: 'Bilder beschriften, erst einzeln beschreiben lassen, dann die Beschreibungen oder Ausschnitte nebeneinander vergleichen.',
    failuresCaveat: 'Diese Zahlen beschreiben die 2023–2025 getesteten Modellversionen. Neuere Modelle schneiden besser ab; OpenAI meldet für o3 etwa Bestwerte auf BlindTest. Miss dein Modell an deinen eigenen Bildern, bevor du dich darauf verlässt.',

    // Teil 3: Werkzeuggestützte Inspektion
    partTools: 'Teil 3: Werkzeuggestützte Inspektion',
    toolsIntro: 'Ein Modell kann nur über Token nachdenken, die es erhalten hat. War das Etikett in der Eingabe 5 px hoch, holt kein noch so langes Nachdenken die Zeichen zurück. Genau das löst ein Zuschneide-Werkzeug: Das Modell nennt eine Region, das Werkzeug schneidet sie aus der Originaldatei aus, und der Ausschnitt wird erneut mit vollem Token-Budget kodiert.',
    lineageTitle: 'Von der Forschung ins Produkt',
    lineage1Title: 'V* / SEAL (Dez. 2023)',
    lineage1Desc: 'Gelenkte visuelle Suche: Das LLM entscheidet, in welcher Region nach fehlenden Details gesucht wird, und gibt den gefundenen Ausschnitt an das Modell zurück.',
    lineage2Title: 'OpenAI o3 / o4-mini (Apr. 2025)',
    lineage2Desc: '„Thinking with images“: Die Modelle schneiden Bilder innerhalb ihres Reasonings zu, zoomen und drehen sie. OpenAI meldet 95,7 % auf V*Bench.',
    lineage3Title: 'Gemini 3 Flash Agentic Vision (Jan. 2026)',
    lineage3Desc: 'Das Modell schreibt und startet Python-Code, um ein Bild zuzuschneiden, zu drehen oder zu annotieren; das Ergebnis wird an den Kontext angehängt. Google meldet 5–10 % Verbesserung auf den meisten Vision-Benchmarks.',
    groundingTitle: 'Grounding: Das Modell muss sagen, wo es hinschauen will',
    groundingDesc: 'Ein Zuschnitt braucht Koordinaten, also muss das Modell eine Bounding Box ausgeben. Die Formate unterscheiden sich: Gemini liefert [y_min, x_min, y_max, x_max], normiert auf 0–1000; Claude liefert Pixelkoordinaten im verkleinerten Bild, das es tatsächlich verarbeitet hat. Wendet man solche Koordinaten ohne Umrechnung auf die Originaldatei an, landet der Ausschnitt an der falschen Stelle. Das ist ein häufiger Fehler in selbst gebauten Werkzeugschleifen.',

    // Demo 3: Zuschneide-Schleife
    loopDemoTitle: 'Die Zuschneide-Schleife Schritt für Schritt',
    loopDemoDesc: 'Gleiches 336-px-Budget wie oben. Die Bounding Box ist für diese Demo vorgegeben, Skalierung und Koordinatenumrechnung werden aber wirklich berechnet.',
    loopStep1: 'Ansehen',
    loopStep1Desc: 'Das Modell erhält das ganze Bild als {tokens} Token. Die Etikettschrift ist nur {cap} px hoch, etwa ein Drittel einer Patch-Kante: nicht lesbar.',
    loopStep2: 'Lokalisieren',
    loopStep2Desc: 'Das Modell gibt eine Bounding Box in seinem eigenen 336 × 336-Eingaberahmen aus und ruft das Zuschneide-Werkzeug auf.',
    loopStep3: 'Handeln',
    loopStep3Desc: 'Das Werkzeug zieht den Padding-Versatz ab, skaliert mit {factor} und schneidet diese Region aus der Originaldatei.',
    loopStep3DescBug: 'Das Werkzeug wendet die Box ohne Umrechnung direkt auf die Originaldatei an. Der Ausschnitt trifft leere Werkbank oben links.',
    loopStep4: 'Beobachten',
    loopStep4Desc: 'Der Ausschnitt wird mit frischem Budget von {tokens} Token kodiert. Die Buchstaben sind jetzt {cap} px hoch, etwa {patches} Patch-Kanten. Bild-Token im Kontext insgesamt: {total}.',
    loopStep4DescBug: 'Die neuen Token zeigen nur Hintergrund. Das Modell muss den Fehlgriff bemerken und es erneut versuchen, was eine weitere Runde kostet.',
    loopBugToggle: 'Fehler simulieren: Koordinaten nicht umrechnen',
    loopToolCall: 'Werkzeugaufruf des Modells',
    loopToolResult: 'Aus dem Original geschnittene Region (px)',
    loopModelView: 'Was das Modell sieht',
    loopOriginalView: 'Originaldatei, 1536 × 1024 px',
    loopReading: 'Jetzt lesbar: SN-4827-XK, in der zweiten Zeile 24 V DC.',
    loopImageAlt: 'Encoder-Eingabe der Zuschneide-Schleife im aktuellen Schritt',
    loopOriginalAlt: 'Original-Referenzbild mit markierter Zuschnittsregion',

    toolsLimitsTitle: 'Was Werkzeuge nicht reparieren',
    toolsLimitsDesc: 'Jeder Zuschnitt kostet eine Runde und neue Bild-Token. Wahrnehmungsfehler bleiben: Das Modell kann die falsche Region wählen oder einen scharfen Ausschnitt verlesen. OpenAI nennt außerdem überflüssige Werkzeugaufrufe und wechselnde Strategien zwischen Versuchen. Ob sich die Schleife lohnt, zeigt nur ein Vergleich mit demselben Modell, denselben Bildern und Fragen, mit und ohne Werkzeuge.',

