    keyTakeaways: 'Das Wichtigste',
    takeaway1: 'Ein Bild gelangt als Vektorfolge ins LLM: ViT-Patches, meist von einem Projektor übersetzt, manchmal per Cross-Attention angebunden oder von Anfang an gemeinsam trainiert.',
    takeaway2: 'Die Auflösung bestimmt die Token-Zahl, und die Token-Zahl bestimmt, welche Details überleben. Was beim Skalieren verloren geht, holt kein Reasoning zurück.',
