    costCacheNote: 'Caching-Annahme: Jeder Aufruf trifft den Cache für das bereits gesehene Präfix. Anthropic berechnet Cache-Lesezugriffe mit 0,1× und 5-Minuten-Cache-Schreibzugriffe mit 1,25× des Basis-Eingabepreises (manche neuere Modelle lesen günstiger). Ausgabe-Tokens sind nicht enthalten.',
