      cacheable: "Identisch mit dem vorherigen Request",
      cacheNote: "Verlauf wird nur angehängt: Alles außer dem neuesten Schritt stimmt mit dem vorherigen Request überein und kann aus dem Cache gelesen werden.",
      cacheBroken: "Der Zeitstempel ändert sich bei jedem Request, das Präfix stimmt also nie überein: keine Cache-Treffer.",
