      colInput: "Eingabetokens",
      colGrowth: "Woher die Eingabe kommt",
      colOutput: "Ausgabetokens",
      colSeconds: "Modellwartezeit (s)",
      colCost: "Kosten",
      chat: "Einzelner Chat-Aufruf",
      agent: "Agent-Aufruf {n}",
      growthStart: "Systemprompt + Aufgabe",
      growthNext: "vorherige Eingabe + {output} Ausgabe + {tool} Tool-Ergebnis",
      formula: "Agent-Eingabe: {inputs} = {inputTotal} Tokens. Ausgabe: {outputs} = {outputTotal} Tokens. Kosten = ({inputTotal} × 1 $ + {outputTotal} × 4 $) / 1.000.000 = {cost}.",
      chatTotal: "Einzelaufruf",
      agentTotal: "Agent, drei Aufrufe",
      timing: "Sequenzielle Latenz = {modelTimes} s Modell + {toolTimes} s Tools = {total} s. Unabhängige Zweige könnten parallel laufen; dann zählt der kritische Pfad statt der Summe.",
      quadratic: "Warum das wichtig ist: Fügt jeder Schritt ungefähr gleich viele Tokens Δ hinzu, hat Schritt k eine Eingabe von etwa I₀ + (k − 1) · Δ. Über n Schritte ergibt das n · I₀ + Δ · n(n − 1) / 2 – die Summe wächst quadratisch mit der Schrittzahl. Prompt Caching senkt den Preis des wiederholten Präfixes, aber nicht seine Länge; Compaction senkt die Länge.",
      linkCaching: "Prompt Caching",
