    keyTakeaways: "Wichtige Erkenntnisse",
    takeaway1: "LLMs können Anweisungen und Daten nicht zuverlässig trennen – jeder Text, den der Agent liest, ist eine mögliche Anweisung.",
    takeaway2: "Indirekte Injection ist bei Agenten der kritische Fall: Der Angreifer handelt mit den Rechten des Nutzers, ohne je mit dem Agenten zu sprechen.",
    takeaway3: "Private Daten + nicht vertrauenswürdige Inhalte + Kommunikation nach außen = Abflussweg. Entferne mindestens eine der drei Eigenschaften.",
    takeaway4: "Filter und Markierungen senken das Risiko, sind aber keine Grenze; adaptive Angreifer kommen an ihnen vorbei.",
    takeaway5: "Setze Berechtigungen im Code durch: Allowlists im Tool-Server, Sandbox mit Kontrolle ausgehender Verbindungen, minimale Rechte.",
    takeaway6: "Reserviere menschliche Freigaben für unumkehrbare Aktionen – und zeige den genauen Aufruf, keine Zusammenfassung.",

