  // Diffusions-Übersicht
  diffusion: {
    title: 'Diffusionsmodelle',
    description: 'Lerne, wie Diffusionsmodelle Struktur aus Rauschen erzeugen, von Grundlagen bis zu Text- und Bildsystemen.',
    whatIs: 'Was sind Diffusionsmodelle?',
    whatIsDesc: 'Diffusionsmodelle lernen, einen schrittweisen Korruptionsprozess umzukehren. Im Training werden Daten nach und nach verrauscht; bei der Generierung sagt das Modell Entrauschungsschritte voraus, bis wieder Struktur entsteht.',
    coreIdea: 'Die Kernintuition',
    coreIdeaDesc: 'Generierung ist iterative Verfeinerung. Statt die ganze Ausgabe in einem Schritt zu erzeugen, verbessert das Modell wiederholt einen verrauschten Zustand und erreicht so oft stabile, hochwertige Samples.',
    textTrackTitle: 'Text-Diffusion',
    textTrackDesc: 'Arbeitet auf maskierten Token-Sequenzen und verfeinert Token-Schätzungen iterativ mit denoising-ähnlichen Updates.',
    imageTrackTitle: 'Bild-Diffusion',
    imageTrackDesc: 'Arbeitet auf latenten Bildrepräsentationen und entrauscht sie zu konsistenten Bildern, gesteuert durch Textbedingungen.',
    roadmapTitle: 'Lernpfad',
    roadmapDesc: 'Folge dieser Reihenfolge, um Intuition von den Grundlagen bis zu modalitiespezifischen Systemen aufzubauen.',
    roadmapFundamentalsTitle: 'Wie Diffusion funktioniert',
    roadmapFundamentalsDesc: 'Vorwärtsrauschen, Rückwärts-Entrauschen, Scheduler und Score-Matching-Intuition.',
    roadmapTextTitle: 'Text-Diffusion',
    roadmapTextDesc: 'Diskrete Token-Diffusion, Mask-and-Predict, Padding und Unterschiede zu autoregressiven Modellen.',
    roadmapImageTitle: 'Bild-Diffusion',
    roadmapImageDesc: 'Latente Pipelines, U-Net vs DiT, Textkonditionierung, CFG und Schritt-Trade-offs.',
    openTopic: 'Thema öffnen',
  },

  // Diffusions-Grundlagen
  diffusionFundamentals: {
    title: 'Wie Diffusion funktioniert',
    description: 'Baue Intuition für Vorwärtskorruption, Rückwärts-Entrauschen, Scheduler und scorebasiertes Lernen auf.',
    forwardProcess: 'Vorwärtsprozess (Korruption)',
    forwardProcessDesc: 'Der Vorwärtsprozess injiziert schrittweise Rauschen in saubere Samples, bis die Struktur weitgehend zerstört ist. So entstehen Trainingspaare, die zeigen, welches Rauschen pro Schritt hinzugefügt wurde.',
    forwardStep1Title: 'Start mit sauberen Daten',
    forwardStep1Desc: 'Ziehe x0 aus echten Daten (Bild, Text-Embedding oder Latent).',
    forwardStep2Title: 'Schrittweise Rauschen addieren',
    forwardStep2Desc: 'Jeder Zeitschritt fügt kontrolliertes gaußsches oder diskretes Rauschen hinzu.',
    forwardStep3Title: 'Nahezu zufälligen Zustand erreichen',
    forwardStep3Desc: 'Nach vielen Schritten nähert sich xT einer einfachen Priorverteilung an.',
    reverseProcess: 'Rückwärtsprozess (Generierung)',
    reverseProcessDesc: 'Die Generierung startet aus Rauschen und wendet gelernte Entrauschungsschritte an. Das Modell sagt einen saubereren Zustand (oder das Rauschresiduum) voraus und bewegt sich iterativ zu realistischen Samples.',
    noisePredictionIntuition: 'Intuition der Rauschvorhersage',
    noisePredictionIntuitionDesc: 'Rauschen zu schätzen ist oft leichter, als direkt das saubere Sample zu prognostizieren. Sobald das Rauschen geschätzt ist, kann es subtrahiert und Struktur progressiv wiederhergestellt werden.',
    schedulers: 'Scheduler: Linear vs Cosine',
    schedulersDesc: 'Scheduler legen fest, wie viel Rauschen pro Schritt hinzugefügt oder entfernt wird. Sie beeinflussen Stabilität, Qualität und Geschwindigkeit stark.',
    schedulerLinearTitle: 'Linearer Scheduler',
    schedulerLinearDesc: 'Rauschen ändert sich pro Schritt mit konstanter Rate. Einfach, vorhersehbar und leicht zu implementieren.',
    schedulerCosineTitle: 'Cosine-Scheduler',
    schedulerCosineDesc: 'Verteilt den Entrauschungsaufwand nichtlinear, behält oft länger nützliches Signal und verbessert die wahrgenommene Qualität.',
    scoreMatching: 'Score-Matching-Intuition',
    scoreMatchingDesc: 'Eine Score-Funktion schätzt den Gradienten der Log-Dichte und zeigt in Richtung wahrscheinlicher Datenbereiche. Entrauschungsupdates folgen dieser Richtung und bewegen verrauschte Zustände zurück auf den Datenmanifold.',
    interactiveTitle: "Vorwärtsprozess mit Gauß-Rauschen",
    interactiveDesc: "Verändere die Signalstärke in der Diffusionsgleichung. Der Rückwärtsprozess wird getrennt erklärt, da ein gelernter Sampler das Originalbild nicht kennt.",
    keyTakeaways: 'Wichtige Erkenntnisse',
    takeaway1: 'Diffusionstraining lernt die Umkehrung eines bekannten Korruptionsprozesses.',
    takeaway2: "Rückwärts-Sampling verwendet eine gelernte Vorhersage. Die Schrittzahl hängt vom Sampler und möglicher Destillation ab.",
    takeaway3: 'Scheduler steuern, wo Modellkapazität über Zeitstufen investiert wird.',
    takeaway4: 'Score-Schätzung liefert eine geometrische Sicht auf die Entrauschungsrichtung.',
  },

