    discreteVsContinuousDesc: 'Sprache ist grundsätzlich diskret, daher nutzen Text-Diffusionsmodelle oft Token-Maskierung und Ersetzung. Manche Ansätze diffundieren in kontinuierlichen Embedding-Räumen und projizieren danach zurück.',
    maskPredict: 'Mask-and-Predict-Paradigma',
