    toolSearchStatsNote: 'Interne Messungen von Anthropic, veröffentlicht im November 2025.',
    toolSearchWhen: 'Anthropic empfiehlt Tool-Suche ab etwa 10 Tools oder 10.000 Tokens an Definitionen und rät, die 3–5 meistgenutzten Tools immer geladen zu lassen. OpenAI bietet denselben Mechanismus (tool_search, defer_loading und Namespaces) ab GPT-5.4 an. Einheitliche Präfixe zahlen sich hier doppelt aus: Eine Suche nach „github“ findet die ganze Gruppe.',
    evals: 'Tools messen statt raten',
