      title: 'Agent-Trajektorien bewerten',
      intro: 'Fünf Trials desselben Support-Agenten an derselben Aufgabe. Jeder Trial läuft gegen eine kleine simulierte Bestelldatenbank; die Transkripte unten entstehen, indem die Tool-Aufrufe des Agenten tatsächlich ausgeführt werden. Schalte Grader an und aus und sieh, welche Trials bestehen – im Vergleich mit einer menschlichen Prüferin, die jedes Transkript gelesen hat.',
