      tauLoophole: { title: 'Wenn der Agent besser war als die Aufgabe', desc: 'In einer Flugbuchungsaufgabe von τ²-bench fand Opus 4.5 eine Lücke in der Airline-Richtlinie, die dem Nutzer besser half – und fiel durch die Eval, wie sie geschrieben war.' },
