    benchDesc: 'Öffentliche Benchmarks helfen, Modelle und Scaffolds auf gemeinsamen Aufgaben zu vergleichen. Vertrauenswürdig macht sie dasselbe wie die eigene Suite: realistische Umgebungen und ergebnisbasierte Bewertung.',
