        grading: 'Versteckte Tests: Zuvor fehlschlagende Tests müssen bestehen, bestehende Tests dürfen nicht brechen. Im Februar 2026 hat OpenAI aufgehört, Ergebnisse zu berichten: In einer Prüfung von 138 schweren Aufgaben hatten 59,4 % fehlerhafte Tests oder Beschreibungen, und Modelle konnten manche Referenz-Patches aus dem Gedächtnis wiedergeben.',
