        grading: 'Jede Aufgabe enthält eine von Menschen geschriebene Lösung und Tests, die den resultierenden Systemzustand prüfen. Läuft über das Harbor-Harness, sodass Claude Code, Codex CLI oder eigene Agenten unter gleichen Bedingungen verglichen werden.',
