    benchCaveat: 'Ein Vorbehalt für alle: Ein Score gehört zu Modell plus Scaffold plus Budget (Schritte, Tokens, Versuche). Leaderboard-Zahlen sind nur bei gleichem Setup vergleichbar – und keine ersetzt Evals auf den eigenen Aufgaben.',

