    securityP2: "Das ist bereits in großem Stil passiert. Anfang 2026 fand Koi Security 341 bösartige Skills auf ClawHub, dem Skill-Marktplatz des Open-Source-Agenten OpenClaw. Ein häufiges Muster war ein gefälschter Abschnitt mit Voraussetzungen in der SKILL.md, der den Agenten anwies, einen Base64-String zu dekodieren und an bash weiterzuleiten – das lud dann die eigentliche Schadsoftware nach.",
