    neuronExample2: 'Gleiche Eingaben, aber b = −3:   z = 2·1 + (−1)·0,5 − 3 = −1,5   →   a = ReLU(−1,5) = 0',
    neuronExampleNote: 'Der negative Bias hat die Schwelle so weit angehoben, dass das Neuron bei diesen Eingaben stumm bleibt.',
    layersTitle: 'Von Neuronen zu Schichten',
    layersDesc: 'Neuronen sind in Schichten angeordnet. Die Eingabeschicht enthält nur die Eingabezahlen. Jedes Neuron einer versteckten Schicht erhält alle Ausgaben der vorherigen Schicht. Die Ausgabeschicht liefert das Ergebnis. Die Information fließt strikt vorwärts; diese Rechnung heißt Forward-Pass (Vorwärtsdurchlauf).',
    layersParamsTitle: 'Parameter zählen',
    layersParamsDesc: 'Jede Verbindung hat ein Gewicht, jedes Neuron nach der Eingabeschicht einen Bias. Das 2-2-1-Netz unten (2 Eingaben, 2 versteckte Neuronen, 1 Ausgabe) hat deshalb 2·2 + 2 = 6 Parameter in der versteckten Schicht und 2·1 + 1 = 3 in der Ausgabeschicht: insgesamt 9.',
    layersScale: 'Am Prinzip ändert die Größe nichts. GPT-3 hat 175 Milliarden Parameter (Brown et al., 2020): dasselbe Multiplizieren, Addieren und Aktivieren, nur unvorstellbar viel öfter.',
