    walkthroughIntro: 'XOR (exklusives Oder) ist der klassische Prüfstein: Die Ausgabe soll 1 sein, wenn genau eine der beiden Eingaben 1 ist, sonst 0. Die Gewichte sind von Hand gewählt, nach dem Beispiel in Goodfellow et al., Deep Learning, Abschnitt 6.1. Wähle eine Eingabe und verfolge jeden Rechenschritt.',
