    nonlinKinkDesc: 'Jedes ReLU-Neuron steuert einen Knick bei. Kombiniert können Knicke Bänder, Ecken und komplexere Bereiche ausschneiden; im XOR-Beispiel ein diagonales Band durch (0, 1) und (1, 0). Mit genügend versteckten Neuronen kann ein Netz mit einer nichtpolynomialen Aktivierung wie ReLU jede stetige Funktion beliebig genau annähern (Leshno et al., 1993). Der Satz garantiert nur, dass solche Gewichte existieren; wie viele Neuronen nötig sind und wie man die Gewichte findet, sagt er nicht.',
