    // Pretraining-Loss
    lossTitle: 'Pretraining: was der Loss misst',
    lossIntro: 'Beim Pretraining liest das Modell eine Sequenz und gibt an jeder Position eine Wahrscheinlichkeitsverteilung über sein gesamtes Vokabular für das nächste Token aus. Der Loss ist der Mittelwert der negativen Log-Wahrscheinlichkeit, die es dem tatsächlich folgenden Token gegeben hat:',
    lossFormula: 'L = −(1/T) · Σₜ log p(xₜ | x₁ … xₜ₋₁)',
    lossExplain: 'Ein sicherer, richtiger Tipp (p = 0,9) kostet 0,11; ein Token, das das Modell für unwahrscheinlich hielt (p = 0,01), kostet 4,6. Dank kausaler Maskierung werden alle Positionen einer Sequenz in einem einzigen Forward Pass bewertet, eine Sequenz mit 8.192 Tokens liefert also 8.192 Trainingssignale. Die Exponentialfunktion des Loss ist die Perplexität: Eine Perplexität von 8 bedeutet, dass das Modell im Schnitt so unsicher ist, als müsste es gleichmäßig zwischen 8 Tokens wählen.',
    lossDemoTitle: 'Loss pro Token',
    lossDemoDesc: 'Die Wahrscheinlichkeiten für das richtige nächste Token sind Beispielwerte für einen frühen und einen späten Checkpoint. Loss und Perplexität werden daraus berechnet.',
    lossEarly: 'Früher Checkpoint',
    lossLate: 'Später Checkpoint',
    lossContextCol: 'Kontext',
    lossTokenCol: 'Nächstes Token',
    lossProbCol: 'p(richtig)',
    lossNllCol: '−log p',
    lossMean: 'Mittlerer Loss',
    lossPerplexity: 'Perplexität',
    lossFloor: 'Auch ein perfektes Modell kann nicht wissen, welches Land auf „Die Hauptstadt von“ folgt. Solche echt unsicheren Tokens halten den Loss über null: Es gibt einen nicht reduzierbaren Anteil, den kein Training beseitigt.',
    lossTokens: {
      t0: 'Die',
      t1: ' Hauptstadt',
      t2: ' von',
      t3: ' Frankreich',
      t4: ' ist',
      t5: ' Paris',
      t6: '.',
    },
    scaleTitle: 'Wie viele Daten pro Parameter?',
    scaleBody: 'Die Chinchilla-Studie (2022) fand, dass bei festem Rechenbudget der Loss bei etwa 20 Trainings-Tokens pro Parameter am niedrigsten ist. Aktuelle Modelle trainieren bewusst weit darüber hinaus, weil ein kleineres Modell, das mehr Daten gesehen hat, im Betrieb günstiger ist: Llama 3 8B sah über 15 Billionen Tokens, rund 1.900 pro Parameter. Der Trainingsaufwand beträgt ungefähr 6 × Parameter × Tokens FLOPs; für Llama 3 405B mit 15,6 Billionen Tokens sind das etwa 3,8 × 10²⁵ FLOPs.',

    // Mid-Training
    midTitle: 'Mid-Training und Kontexterweiterung',
    midIntro: 'Der letzte Teil des Pretrainings wird zunehmend als eigene Phase behandelt. Der Loss bleibt gleich; Daten und Lernrate ändern sich.',
    annealTitle: 'Annealing auf hochwertigen Daten',
    annealBody: 'Während die Lernrate gegen null abfällt, wird die Mischung zu kuratierten Quellen verschoben: Mathematik, Code, lehrbuchartige und synthetische Texte. Updates mit kleiner Lernrate am Trainingsende werden nicht mehr überschrieben, deshalb zahlt sich Datenqualität hier am stärksten aus. Laut Llama-3-Bericht verbesserte Annealing mit hochgewichteten Qualitätsdaten ein vortrainiertes 8B-Modell um 24,0 % auf GSM8K und 6,4 % auf MATH. OLMo 2 nennt diese Phase Mid-Training und nutzt dafür eine eigene Mischung (Dolmino). Kurze Annealing-Läufe dienen außerdem als günstiger Test, ob ein neuer Datensatz hilft.',
    longTitle: 'Kontexterweiterung',
    longBody: 'Pretraining auf Sequenzen mit 4K–8K Tokens ist viel günstiger, weil die Kosten der Attention mit der Sequenzlänge wachsen. Das Kontextfenster wird am Ende erweitert: Die RoPE-Basisfrequenz wird erhöht (Qwen3: von 10.000 auf 1.000.000), damit weit entfernte Positionen weiterhin auf unterscheidbare Rotationen abgebildet werden, und das Modell trainiert auf langen Dokumenten. Llama 3 ging in sechs Schritten über etwa 800 Milliarden Tokens von 8K auf 128K Tokens. Qwen3 trainiert die letzte Phase mit 32K Tokens und erreicht 128K bei der Inferenz mit YaRN.',
    longLink: 'Wie RoPE Positionen kodiert:',

    // Post-Training
    postTitle: 'Post-Training: vom Textvorhersager zum Assistenten',
    sftTitle: 'Supervised Fine-Tuning (SFT)',
    sftBody: 'SFT nutzt denselben Next-Token-Loss, aber auf Gesprächen in einem festen Chat-Template. Prompt-Tokens werden aus dem Loss maskiert, das Modell lernt also nur, den Assistenten-Teil zu erzeugen. SFT vermittelt Format und Stil schnell. Für neue Fakten taugt es wenig: Gekhman et al. (2024) fanden, dass Fakten, die das Basismodell nicht kannte, beim Fine-Tuning nur langsam gelernt werden und Halluzinationen verstärken. Das Wissen stammt aus dem Pretraining; SFT bringt dem Modell bei, es zu nutzen.',
    methodsTitle: 'PPO, DPO und GRPO',
    methodsIntro: 'Drei verbreitete Wege, aus einem Lernsignal Gewichts-Updates zu machen. PPO und GRPO sind Reinforcement Learning, DPO ist es nicht.',
    ppoTitle: 'RLHF mit PPO',
    ppoBody: 'Das InstructGPT-Rezept (2022): Menschen vergleichen Antworten, ein Reward-Modell lernt ihre Wahl vorherzusagen, und PPO optimiert das Modell auf diese Belohnung.',
    ppoSteps: {
      s1: 'Menschliche Vergleiche von zwei oder mehr Antworten auf denselben Prompt sammeln.',
      s2: 'Ein Reward-Modell trainieren, das bevorzugten Antworten höhere Werte gibt.',
      s3: 'Antworten aus dem aktuellen Modell samplen, bewerten und mit PPO updaten. Ein Value-Modell (Critic) senkt die Varianz; eine KL-Strafe hält das Modell nahe an der SFT-Version.',
    },
    dpoTitle: 'DPO: Präferenzen ohne RL',
    dpoBody: 'DPO (2023) zeigt, dass das KL-regularisierte RLHF-Ziel ein Optimum in geschlossener Form hat. Die Belohnung lässt sich daher als Verhältnis der Log-Wahrscheinlichkeiten von trainiertem Modell und eingefrorenem Referenzmodell ausdrücken.',
    dpoSteps: {
      s1: 'Von einem festen Datensatz aus (Prompt, bevorzugte Antwort, abgelehnte Antwort) starten.',
      s2: 'Log-Wahrscheinlichkeiten beider Antworten unter dem trainierten Modell und dem eingefrorenen Referenzmodell berechnen.',
      s3: 'Einen logistischen Loss minimieren, der die bevorzugte Antwort gegenüber der abgelehnten anhebt. Es wird nichts gesampelt und keine Belohnung berechnet: Das ist überwachtes Lernen auf Präferenzdaten.',
    },
    dpoFormula: 'L = −log σ(β · [log π(y⁺|x)/π_ref(y⁺|x) − log π(y⁻|x)/π_ref(y⁻|x)])',
    grpoTitle: 'GRPO',
    grpoBody: 'GRPO (DeepSeekMath, 2024) ist PPO ohne Critic. Die Vergleichsbasis für jede Antwort ist die mittlere Belohnung der anderen Antworten auf denselben Prompt.',
