      s3: 'Die gruppennormierte Belohnung Aᵢ = (rᵢ − Mittelwert) / Standardabweichung als Advantage nutzen: Antworten, die besser als ihre Geschwister sind, werden verstärkt, schlechtere abgeschwächt.',
