    // RLVR
    rlvrTitle: 'RL mit überprüfbaren Belohnungen: der Standard für Reasoning-Modelle',
    rlvrIntro: 'Ein gelerntes Reward-Modell lässt sich austricksen: Die Policy findet Antworten, die hoch bewertet werden, ohne gut zu sein. Bei Mathematik, Code und vielen formalen Aufgaben kann stattdessen ein Programm das Ergebnis prüfen. Tülu 3 (2024) nannte das Reinforcement Learning with Verifiable Rewards (RLVR). DeepSeek-R1-Zero (2025) wendete RLVR mit GRPO direkt auf ein Basismodell an, und lange Gedankenketten, Selbstprüfungen und Zurückgehen entstanden ohne von Menschen geschriebene Reasoning-Beispiele; das veröffentlichte R1 stellte für bessere Lesbarkeit eine kleine SFT-Phase voran. Seitdem ist RLVR eine Standardphase im Training von Reasoning-Modellen.',
    rlvrDemoTitle: 'GRPO-Advantages für einen Prompt',
    rlvrDemoDesc: 'Das Modell sampelt 8 Antworten auf dieselbe Aufgabe, ein Exact-Match-Verifier vergibt Belohnung 1 oder 0. Verschiebe den Regler, um zu ändern, wie viele davon richtig sind; die Advantages werden wie bei GRPO berechnet.',
