      t5: 'RLVR belohnt Antworten, die ein Programm prüfen kann, und ist der Weg, auf dem Reasoning-Modelle trainiert werden. Aufgaben, die immer oder nie gelöst werden, liefern kein Lernsignal.',
      t6: 'Labore kombinieren und wiederholen diese Phasen in unterschiedlicher Reihenfolge. Rezepte vergleicht man nach Daten, Ziel und Umfang, nicht nach Phasennamen.',
