        example: "In verbreiteten Hate-Speech-Datensätzen wurden Tweets in African American English bis zu doppelt so häufig als beleidigend gelabelt. Darauf trainierte Modelle übernahmen das Muster.",
        source: "Sap et al., 2019",
        href: "https://aclanthology.org/P19-1163/",
