    // Results
    resultsTitle: 'Was es bringt: veröffentlichte Zahlen',
    resultsHazy1: 'Hazy Research, Llama-3.2-1B bei Batchgröße 1 (Mai 2025): etwa 78 % der Speicherbandbreite einer H100, gegenüber höchstens etwa 50 % bei vLLM und SGLang auf derselben Last. Unter 1 ms pro Forward-Pass auf der H100 (≈2,5× schneller als vLLM, >1,5× schneller als SGLang) und unter 680 µs auf der B200 (>3,5× schneller als vLLM). Die Vergleichssysteme nutzten CUDA Graphs und torch.compile.',
    resultsHazy2: 'Hazy Research, Llama-70B mit 8-fachem Tensor-Parallelismus (Sept. 2025): ein Durchsatz-Megakernel mit gemischtem Prefill/Decode und überlappter Kommunikation zwischen den GPUs, integriert in die Engine Tokasaurus, erreichte auf einem ShareGPT-Benchmark mehr als 22 % höheren End-to-End-Durchsatz als SGLang.',
    resultsMpk: 'Mirage Persistent Kernel (MPK, Dez. 2025): ein Compiler, der ein Modell automatisch in einen Megakernel übersetzt. Er baut einen Aufgabengraphen auf der Ebene einzelner SMs, verteilt die Aufgaben innerhalb des Kernels ohne zentralen Scheduler und bildet Pipelines über Operatorgrenzen hinweg. Das Paper berichtet bis zu 1,7× geringere End-to-End-Latenz als Serving-Systeme mit einem Kernel pro Operator, auf A100, H100 und B200.',

    // Persistent / MoE
    persistentTitle: 'Persistente Kernels und MoE',
    persistentIntro: 'Ein Megakernel ist ein persistenter Kernel: einmal gestartet, bleiben seine Thread-Blöcke auf den SMs und arbeiten in einer Schleife eine Warteschlange ab, statt sich zu beenden.',
    persistentLoopTitle: 'Eine MoE-Schicht in der Schleife',
    persistentLoopDesc: 'Der Router entscheidet, zu welchen Experten jedes Token geht – erst dann wissen die Experten-MLPs, wie viel Arbeit sie haben.',
    persistentLoop1: 'Attention',
    persistentLoop2: 'Router',
    persistentLoop3: 'Experten-MLPs',
    persistentLoopAgain: 'nächste Schicht',
    persistentMoeTitle: 'Warum das zu MoE passt',
    persistentMoeDesc: 'Wie viele Tokens jeder Experte erhält, steht erst fest, nachdem der Router auf der GPU gelaufen ist. Bei getrennten Kernels sind die Shapes beim Launch festgelegt: Entweder wird die Arbeit für den schlimmsten Fall bemessen, oder die CPU wartet auf das Router-Ergebnis. Ein persistenter Kernel kann die Router-Ausgabe direkt lesen und nur die Experten-Kacheln verteilen, die tatsächlich Tokens haben – hilfreich bei kleinen Batches, in denen viele Experten nur eine Handvoll Tokens bekommen.',

    // When not
    whenNotTitle: 'Wann sich ein Megakernel nicht lohnt',
    whenNot1: 'Große Batches und Prefill: Mit Tausenden Tokens pro Schritt sind die großen Matrixmultiplikationen rechenbegrenzt und dauern so lange, dass ein paar Mikrosekunden pro Grenze kaum ins Gewicht fallen. Dort ist Batching der größere Hebel.',
    whenNot2: 'Aufwand und Portierbarkeit: Ablaufplan, Seitengrößen und Synchronisation sind auf ein Modell und eine GPU-Generation zugeschnitten; eine neue Architektur oder GPU bedeutet oft einen Neuanfang. Compiler wie MPK sollen genau das automatisieren.',
    whenNot3: 'Ressourcenbedarf: Ein einzelner Kernel muss die Register und das Shared Memory seiner anspruchsvollsten Instruktion reservieren, was die Auslastung für alle anderen begrenzen kann.',
    whenNot4: 'Debugging und Integration: Ein falscher Zähler-Zielwert blockiert die ganze GPU, statt einen einzelnen Kernel scheitern zu lassen, und Serving-Funktionen wie ein paginierter KV-Cache, Continuous Batching und variable Shapes müssen in den Kernel selbst eingebaut werden.',

    // Insight & takeaways
    keyInsightTitle: 'Die Kernidee',
    keyInsightFusionLabel: 'Kernel-Fusion',
    keyInsightFusion: 'spart Bytes: Zwischenergebnisse bleiben auf dem Chip.',
    keyInsightGraphLabel: 'CUDA Graph',
    keyInsightGraph: 'spart CPU-Arbeit: viele Launches werden zu einem Replay.',
    keyInsightMegaLabel: 'Megakernel',
    keyInsightMega: 'spart Leerlauf: Die Speicherleitung wartet nie auf eine Kernelgrenze.',
    keyTakeaways: 'Das Wichtigste',
    takeaway1: 'Bei Batchgröße 1 ist ein Decode-Schritt durch Gewichtsbytes ÷ Speicherbandbreite begrenzt; entscheidend ist, wie viel der Zeit die Speicherleitung tatsächlich arbeitet.',
    takeaway2: 'Fusion beseitigt HBM-Umwege innerhalb eines Kernels, CUDA Graphs verbilligen Launches – beide behalten aber Kernelgrenzen mit ihren Nachzügler- und Lade-Bubbles.',
    takeaway3: 'Ein Megakernel ersetzt Grenzen durch einen Instruktionsplan auf der GPU, Shared-Memory-Seiten und Zähler, sodass die nächsten Gewichte laden, während der aktuelle Schritt endet.',
    takeaway4: 'Er lohnt sich vor allem für Decoding mit niedriger Latenz und kleinen Batches; bei großen Batches und Prefill zählen Batching und gute Matrix-Kernels mehr.',

