    notIdeal3: 'Prompts, bei denen sich das Präfix häufig zwischen Anfragen ändert',
    costTitle: 'Kosten & Performance',
    costDesc: 'Die Einsparungen durch Prompt Caching sind erheblich, besonders für Anwendungen mit langen, wiederholten Prompt-Präfixen. Hier sind die Zahlen der großen Anbieter:',
    costSaving: 'Kostenreduktion bei gecachten Tokens (Anthropic)',
    speedBoost: 'schnellere Time-to-First-Token (Anthropic)',
