    codeTitle: 'Code-Beispiel: Anthropic API',
    codeDesc: 'Anthropics Implementierung gibt dir explizite Kontrolle darüber, was gecacht wird. Füge cache_control zu jedem Inhaltsblock in deinem System-Prompt oder Nachrichten hinzu:',
    tipsTitle: 'Implementierungstipps',
    tip1Title: 'Statischen Inhalt zuerst',
    tip1Desc: 'Cache-Matching funktioniert auf Präfixen. Platziere deinen System-Prompt und Few-Shot-Beispiele vor dynamischem Inhalt, damit das Präfix über Anfragen hinweg stabil bleibt.',
    tip2Title: 'Minimale Token-Anzahl beachten',
    tip2Desc: "Prüfe die minimale cachebare Prefixlänge für das konkrete Modell. Ein Prefix kann stabil und trotzdem zu kurz sein.",
    tip3Title: 'TTL verstehen',
    tip3Desc: "Berücksichtige Lebensdauer, Verlängerung und Routing des Anbieters. Wiederverwendung nach Ablauf kann einen neuen Write erfordern. Miss Misses, statt bei jedem wiederholten Prompt einen Hit anzunehmen.",
    tip4Title: 'Cache-Hit-Raten überwachen',
    tip4Desc: 'Prüfe die Usage-Felder in API-Antworten (cache_creation_input_tokens vs cache_read_input_tokens), um zu verifizieren, dass Caching funktioniert. Niedrige Hit-Raten bedeuten, dass sich dein Präfix zu oft ändert.',
    takeawaysTitle: 'Wichtige Erkenntnisse',
    takeaway1: 'Prompt Caching verwendet berechnete KV-Paare über API-Anfragen hinweg wieder und überspringt redundante Berechnungen für wiederholte Prompt-Präfixe.',
    takeaway2: "Die Ersparnis hängt von Modell, Write-/Read-Preisen, Lebensdauer und Trefferrate ab. Vergleiche die vollständige Arbeitslast.",
    takeaway3: 'Am besten für lange System-Prompts, Few-Shot-Beispiele und große Dokumente, die mehrfach abgefragt werden.',
    takeaway4: 'Strukturiere Prompts mit statischem Inhalt zuerst (Präfix) und dynamischem Inhalt zuletzt, um Cache-Hit-Raten zu maximieren.',
