    rlIntro: "Der Agent aktualisiert Q-Werte anhand von Rewards. Pfeile zeigen die derzeit bevorzugte Aktion. Exploration verändert die gesammelten Erfahrungen; vergleiche deshalb mehrere Läufe.",
