    title: 'VRAM-Rechner',
    description: 'Abschätzen, ob ein Modell in GPU- oder Unified Memory passt: Gewichte, KV-Cache und Runtime-Reserve, mit allen Annahmen sichtbar.',

    introTitle: 'Drei Dinge teilen sich den Speicher',
    introDesc: 'Ein laufendes Modell braucht Platz für seine Gewichte, für den KV-Cache, der mit jedem Kontext-Token wächst, und für Runtime-Puffer. Der Rechner addiert die drei. Das ist nur eine Kapazitätsprüfung: Ob ein Modell passt, sagt noch nichts über sein Tempo. Das Tempo folgt weiter unten.',
    partWeightsTitle: 'Gewichte',
    partWeightsDesc: 'Alle Parameter, auch sämtliche MoE-Experten, mal die Bits des gewählten Formats. Steht fest, sobald die Datei gewählt ist.',
    partKvTitle: 'KV-Cache',
    partKvDesc: 'Keys und Values aller bisherigen Tokens, pro Attention-Schicht. Wächst linear mit der Kontextlänge und mit der Zahl paralleler Sequenzen.',
    partReserveTitle: 'Runtime-Reserve',
    partReserveDesc: 'Rechenpuffer, CUDA-/Metal-Kontext und Fragmentierung. Hängt von Runtime und Batchgröße ab und ist hier deshalb eine veränderbare Annahme.',

