    presetNotes: {
      gptOss20b: '21 Mrd. Parameter, 3,6 Mrd. aktiv. Die 24 Schichten wechseln zwischen voller Attention und einem Sliding Window von 128 Tokens, deshalb wachsen nur 12 Schichten mit dem Kontext. 8 KV-Heads × 64. Die Expertengewichte erscheinen in MXFP4 (≈4,25 Bit), was die Q4-Einstellung annähert.',
      qwen36_27b: 'Dichtes 27B-Modell mit hybrider Architektur: 48 von 64 Schichten sind Gated DeltaNet (lineare Attention mit einem Zustand fester Größe statt eines Caches), jede vierte Schicht ist volle Attention mit 4 KV-Heads × 256. Der DeltaNet-Zustand von etwa 144 MiB pro Sequenz ist nicht enthalten.',
      qwen36_35bA3b: '35 Mrd. Parameter, 3 Mrd. aktiv (8 von 256 Experten). 30 Gated-DeltaNet-Schichten plus 10 Schichten mit voller Attention und 2 KV-Heads × 256: nur etwa 20 KiB KV-Cache pro Token. Der DeltaNet-Zustand von etwa 60 MiB pro Sequenz ist nicht enthalten.',
      minimaxM27: 'Etwa 229 Mrd. Parameter, etwa 10 Mrd. aktiv. Alle 62 Schichten nutzen volle Attention mit 8 KV-Heads × 128, also etwa 248 KiB pro Token: Bei 200.000 Tokens erreicht der Cache etwa 47 GiB pro Sequenz.',
      glm51: '744 Mrd. Parameter, 40 Mrd. aktiv. Multi-Head Latent Attention: 512 latente Werte plus ein 64-dimensionaler Positions-Key pro Token und Schicht, 78 Schichten. Der Indexer von DeepSeek Sparse Attention speichert zusätzlich einen 128-dimensionalen Key pro Token und Schicht (oft in FP8); er ist nicht enthalten.',
      kimiK26: '1 Billion Parameter, 32 Mrd. aktiv. Multi-Head Latent Attention im Layout von DeepSeek-V3: 61 Schichten × 576 Werte, etwa 69 KiB pro Token in BF16. Ein 256K-Kontext braucht etwa 17 GiB pro Sequenz, wenig im Vergleich zu den Gewichten.',
      llamaMaverick: '400 Mrd. Parameter, 17 Mrd. aktiv. 36 von 48 Schichten nutzen Chunked Attention mit Blöcken von 8.192 Tokens; nur jede vierte Schicht (global, ohne RoPE) behält den ganzen Kontext. Runtimes ohne Chunked Attention legen für alle 48 Schichten einen vollen Cache an: Dann die Fenster-Schichten auf 0 setzen.',
    },
    paramLabel: 'Gesamtparameter (Milliarden)',
    activeParamLabel: 'Aktive Parameter pro Token (Milliarden)',
    layersLabel: 'Schichten (n_layers)',
    kvLayersLabel: 'Schichten mit KV-Cache über den ganzen Kontext',
    layoutLabel: 'KV-Layout',
