    quantLabel: 'Gewichtsformat',
    bitsUnit: 'Bit',
    quantNote: 'Die Q-Stufen sind beispielhafte Speicherbudgets: Bits × Overhead für Block-Skalierungen. Echte GGUF-Dateien mischen Tensorformate; für die Hardware-Wahl zählt die tatsächliche Dateigröße.',
    weights: 'Gewichte',
    kv: 'KV-Cache',
