    demoPasses: 'Forward-Passes',
    demoTokens: 'Festgeschriebene Tokens',
    demoRatio: 'Tokens pro Durchlauf',
    demoTheory: 'Erwartet: 1 + α = {value}',
    demoLegendMain: 'aus dem Haupt-Head',
    demoLegendAccepted: 'angenommener MTP-Entwurf',
    demoLegendRejected: 'abgelehnter Entwurf',
