    caveatsTitle: 'Einschränkungen',
    caveat1: 'Kleine Modelle werden schlechter: Das zusätzliche Ziel konkurriert um begrenzte Kapazität. Der Nutzen zeigt sich erst ab etwa 1B Parametern.',
    caveat2: 'Jede weitere Tiefe kostet im Training eine zusätzliche vokabulargroße Ausgabeberechnung und wird bei der Inferenz seltener angenommen; jenseits von D = 1 fällt der Ertrag schnell ab.',
    caveat3: 'Die Beschleunigung gibt es nur, wenn der Serving-Stack MTP-Entwürfe implementiert. Sonst sind die Module totes Gewicht und werden einfach verworfen.',

    keyTakeaways: 'Wichtigste Punkte',
    takeaway1: 'MTP ergänzt den gewöhnlichen Next-Token-Loss um Terme für die Tokens t+2, t+3, … – entweder mit unabhängigen parallelen Köpfen oder mit kausal verketteten Modulen.',
    takeaway2: 'Als Trainingsziel verbessert es die Sample-Effizienz großer Modelle – und schadet kleinen.',
