    budgetForcingTitle: 'Budget Forcing: der Mechanismus sichtbar gemacht',
    budgetForcingDesc: 'Das s1-Paper (Muennighoff et al., 2025) steuert die Denklänge direkt beim Decoding. Zum frühen Abbruch wird das Ende-des-Denkens-Trennzeichen erzwungen. Zum Verlängern wird es unterdrückt und „Wait“ angehängt – das Modell prüft dann oft nach und korrigiert seine Antwort. Ein 32B-Modell, feinjustiert mit nur 1.000 Beispielen, wurde bei Wettbewerbsmathematik mit wachsendem erzwungenem Budget stetig besser.',
