      rareSignal: 'Ein seltener Erfolg bekommt einen großen positiven Advantage. So verstärkt RLVR Verhalten, das das Modell bereits gelegentlich zeigt.',
      normalSignal: 'Richtige Antworten werden nach oben geschoben, falsche nach unten. Die Advantages einer Gruppe summieren sich immer zu null.',
