    practiceCaveatTitle: 'Was RLVR hinzufügt – und was nicht',
    practiceCaveat: 'Yue et al. (NeurIPS 2025) verglichen RLVR-Modelle mit ihren Basismodellen anhand von pass@k. Bei k = 1 gewinnt RLVR deutlich, doch mit vielen Samples (großes k) löst das Basismodell mehr Aufgaben. Ihre Deutung: RLVR macht vor allem Lösungswege wahrscheinlicher, die das Basismodell schon enthält, statt neue zu erschaffen. Das passt zum GRPO-Mechanismus oben: Belohnt werden kann nur Verhalten, das das Modell tatsächlich sampelt.',
    verifierTitle: 'Verifier vs. Reward-Modell',
