    gpuWorkTitle: 'GPU-Seite',
    gpuWorkDesc: 'Rollouts mit der aktuellen Policy sampeln, Log-Wahrscheinlichkeiten berechnen und die Gewichte aktualisieren. Bei langen Reasoning-Traces und Agenten-Trajektorien nimmt die Generierung einen großen Teil jedes Trainingsschritts ein.',
