    hardPartNote: 'RLVR für Agenten zu skalieren ist deshalb nicht nur ein GPU-Problem. Ohne genug zuverlässige, schnell zurücksetzbare Umgebungen warten die GPUs untätig auf Rewards.',
    strategicTitle: 'Wo RLVR funktioniert',
    strategicDesc: 'RLVR greift, wenn drei Bedingungen erfüllt sind: Das Ergebnis lässt sich automatisch und billig prüfen, das aktuelle Modell hat schon manchmal Erfolg (sonst bekommt jede Gruppe nur Nullen), und die Prüfung deckt ab, worauf es wirklich ankommt. Mathematik und Code erfüllen alle drei – deshalb konzentriert sich der Fortschritt beim Reasoning dort. Für Schreibqualität oder Forschungsurteil greifen Teams auf Reward-Modelle oder rubrikbasierte Bewerter zurück, mit den oben beschriebenen Schwächen.',
