    footDerived: '* abgeleitet: Wert pro Chip aus einem Systemgesamtwert oder die Hälfte eines Sparse-Werts.',
    footSparsity: 'Datenblatt-Falle: Hersteller nennen oft Werte „mit Sparsity“ (2:4-Sparsity – zwei von vier Gewichten sind null), was die Zahl verdoppelt. Gewöhnliche LLM-Gewichte folgen diesem Muster nicht, deshalb verwendet diese Seite dichte Werte.',
    footSram: 'SRAM-Bandbreite ist On-Die-Bandbreite und nicht direkt mit HBM vergleichbar; die Kapazität pro Chip ist viel kleiner. Für diese Chips wird kein Ridge angegeben.',
    familiesTitle: 'Beschleuniger-Familien',
    familiesIntro: 'Alle kombinieren Matrix-Einheiten mit schnellem Speicher. Sie unterscheiden sich darin, wie viel sie fest verdrahten, wo die Gewichte liegen und welchen Software-Stack man übernehmen muss.',
    familyGpuTitle: 'GPU (NVIDIA, AMD)',
    familyGpu: 'Programmierbare Kerne plus Tensor Cores für Matrixrechnung, mit dem breitesten Software-Ökosystem (CUDA, ROCm, PyTorch-Kernels). Die Flexibilität kostet etwas Effizienz, übersteht aber Architekturwechsel – neue Attention-Varianten oder MoE-Routing laufen ab Tag eins.',
    familyTpuTitle: 'TPU (Google)',
    familyTpu: 'Ein ASIC rund um große systolische Matrix-Einheiten, programmiert über den XLA-Compiler (JAX, PyTorch/XLA). Ein eigenes Chip-zu-Chip-Netz verbindet bis zu 9.216 Ironwood-Chips in einem Pod. Nur in Google Cloud verfügbar.',
    familyHyperTitle: 'Hyperscaler-ASICs (AWS Trainium, Microsoft Maia, Meta MTIA)',
    familyHyper: 'Dasselbe Rezept – HBM plus Matrix-Einheiten –, aber für die eigene Flotte und den eigenen Software-Stack entworfen (AWS Neuron SDK, Maia SDK). Ziel sind Kosten pro Token und Unabhängigkeit von einem einzigen Lieferanten, nicht Rekordwerte.',
    familySramTitle: 'SRAM-zentrierte Designs (Groq, Cerebras)',
    familySram: 'Halten die Gewichte im On-Chip-SRAM statt im HBM. Extreme Bandbreite und niedrige Latenz pro Token, aber wenig Kapazität pro Chip – große Modelle brauchen Hunderte Chips oder einen ganzen Wafer, was Kosten und Flexibilität prägt.',
    familyAsicTitle: 'Transformer-ASICs (z. B. Etched Sohu)',
    familyAsic: 'Verdrahten den Transformer selbst. Maximale Spezialisierung: Die Wette geht nur auf, wenn Architekturen transformerförmig bleiben. Etched hat große Beschleunigungsversprechen veröffentlicht, aber keine unabhängig geprüften Benchmarks.',
    familyNpuTitle: 'NPU (Smartphones, Laptops)',
    familyNpu: 'Kleine Inferenz-Beschleuniger für wenige Watt. Sie teilen sich meist den LPDDR-Speicher des Systems, dessen Bandbreite weit unter HBM liegt – deshalb ist lokales LLM-Decoding noch stärker memory-bound. Unterstützte Operatoren und Hersteller-Tools schränken oft ein, welche Modelle laufen.',
    familyFpgaTitle: 'FPGA',
    familyFpga: 'Rekonfigurierbare Logik für eine eigene Pipeline, etwa für Inferenz mit niedriger Latenz in Netzwerkhardware. Operatoren abzubilden und den Speicherdurchsatz zu halten, kostet viel Engineering; für große LLMs spielen FPGAs eine Nischenrolle.',
    checklistTitle: 'Bevor du einen Chip auswählst',
    checkMemory: 'Passen Gewichte plus KV-Cache für deinen Kontext und Batch in den Speicher – oder auf wie viele Chips verteilt?',
    checkBound: 'Ist dein Workload Decode-lastig (Bandbreite zählt) oder Prefill-/Trainings-lastig (FLOPs zählen)?',
    checkOperators: 'Unterstützen Compiler und Runtime jeden Operator und jede Präzision, die du brauchst (z. B. FP8, MoE-Routing, deine Attention-Variante)?',
    checkScale: 'Wie schnell ist der Interconnect zwischen den Chips, wenn das Modell aufgeteilt werden muss?',
    checkCost: 'Was kosten Hardware, Strom, Kühlung, Hosting und Engineering-Zeit pro Million Tokens?',
    strategicTitle: 'Der strategische Grund, warum Unternehmen eigene Chips bauen',
    strategicDesc1: 'Bei Custom Silicon geht es nicht nur um Spitzengeschwindigkeit. Es geht um Liefersicherheit, Marge, Kontrolle über die Roadmap und darum, nicht von einem einzigen Anbieter abzuhängen. Google TPUs, AWS Trainium, Microsoft Maia und Meta MTIA spiegeln denselben Druck wider: Die KI-Nachfrage ist so groß, dass Hardware zur Produktstrategie wird. Microsoft etwa positioniert Maia 200 (Januar 2026) ausdrücklich über die Leistung pro Dollar bei Inferenz in der eigenen Flotte.',
    strategicDesc2: 'Das Risiko ist real: Ist der Software-Stack schwach oder verschiebt sich die Modellarchitektur, kann ein spezialisierter Chip zur teuren Sackgasse werden. Die gewinnende Plattform ist meist Chip plus Compiler plus Kernels plus Networking plus Developer Experience.',
    strategicDesc3: 'Inferenz-Spezialisten sind selbst zu strategischen Gütern geworden: Im Dezember 2025 hat NVIDIA Groqs Inferenz-Technologie nicht exklusiv lizenziert, Groqs Gründer und Präsident wechselten zu NVIDIA. Groq bleibt ein eigenständiges Unternehmen und betreibt GroqCloud weiter.',
    sourcesTitle: 'Quellen und weiterführende Literatur',
    srcRoofline: 'Williams, Waterman, Patterson (2009): Roofline – an insightful visual performance model',
    srcScalingBook: 'JAX Scaling Book: All about rooflines',
    srcMemoryWall: 'Gholami et al. (2024): AI and Memory Wall',
    srcHbm4: 'JEDEC (April 2025): HBM4-Standard JESD270-4',
